css:
.card-container {
  width: 260px;
  background: linear-gradient(
    to top right,
    #975af4,
    #2f7cf8 40%,
    #78aafa 65%,
    #934cff 100%
  );
  padding: 4px;
  border-radius: 32px;
  display: flex;
  flex-direction: column;
}
.card-container .title-card {
  display: flex;
  align-items: center;
  padding: 16px 18px;
  justify-content: space-between;
  color: #fff;
}
.card-container .title-card p {
  font-size: 14px;
  font-weight: 600;
  font-style: italic;
  text-shadow: 2px 2px 6px #2975ee;
}

.card-container .card-content {
  width: 100%;
  height: 100%;
  background-color: #161a20;
  border-radius: 30px;
  color: #838383;
  font-size: 12px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.card-container .card-content .title {
  font-weight: 600;
  color: #bab9b9;
}
.card-container .card-content .plain :nth-child(1) {
  font-size: 36px;
  color: #fff;
}
.card-container .card-content .card-btn {
  background: linear-gradient(
    4deg,
    #975af4,
    #2f7cf8 40%,
    #78aafa 65%,
    #934cff 100%
  );
  padding: 8px;
  border: none;
  width: 100%;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 12px;
  transition: all 0.3s ease-in-out;
  cursor: pointer;
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.6);
}
.card-container .card-content .card-btn:hover {
  color: #ffffff;
  text-shadow: 0 0 8px #fff;
  transform: scale(1.03);
}
.card-container .card-content .card-btn:active {
  transform: scale(1);
}
.card-container .card-content .card-separate {
  display: flex;
  gap: 8px;
  align-items: center;
  width: 100%;
  font-size: 10px;
  color: rgb(131, 131, 131, 0.5);
}
.card-container .card-content .card-separate .separate {
  width: 100%;
  height: 1px;
  background-color: rgb(131, 131, 131, 0.5);
}

.card-container .card-content .card-list-features {
  color: #bab9b9;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card-container .card-content .card-list-features .option {
  display: flex;
  gap: 8px;
  align-items: center;
}
